package android.content; import java.util.*; public class ContentValues{public final LinkedHashMap<String,Object> values=new LinkedHashMap<>();public void put(String k,String v){values.put(k,v);}public void put(String k,Integer v){values.put(k,v);}public void put(String k,Long v){values.put(k,v);}public void put(String k,Boolean v){values.put(k,v==null?null:v?1:0);}public void putNull(String k){values.put(k,null);}public void clear(){values.clear();}}
